visible.script:
let layer, seq=0, first=false, held=false;
function state(){return {runtime:engine.runtime,visible:layer.visible,frame:layer.getFrame(),playing:layer.isPlaying(),rate:layer.rate,frameCount:layer.frameCount};}
function log(label,value){if(seq>=8)return;console.log('SKWD_A02:'+JSON.stringify({probe:"visible-control",version:1,cell:1,seq:++seq,kind:'diagnostic',label,fields:[value]}));}
function call(fn){try{const value=fn();return {returnType:typeof value,returned:value,state:state()}}catch(error){return {error:{name:String(error?.name),message:String(error?.message)},state:state()}}}
export function init(){layer=thisLayer.getAnimationLayer('Animación 1');log('init',state());log('seek',call(()=>layer.setFrame(120)));return true;}
export function update(){if(!first){first=true;log('first-update',state());}if(!held&&engine.runtime>=0.6){held=true;log('held',state());}return true;}
